static unsigned probeLow,probeHigh,irqLow,irqHigh;
static void initProbe(struct mCore*c,const char*sy){unsigned cpsr,sp;do{assert(c->readRegister(c,"cpsr",&cpsr));if((cpsr&31)==31&&c->busRead16(c,0x04000208)==1)break;c->step(c);}while(1);assert(c->readRegister(c,"sp",&sp));probeLow=address(sy,"__iwram_overlay_end");probeHigh=(sp-64)&~3u;irqLow=address(sy,"__sp_usr");irqHigh=address(sy,"__sp_irq");assert(probeHigh>probeLow&&probeHigh<irqLow);for(unsigned a=probeLow;a<probeHigh;a+=4)c->busWrite32(c,a,0xDDAADDCC);for(unsigned a=irqLow;a<irqHigh;a+=4)c->busWrite32(c,a,0xDDAADDCC);}
static void endProbe(struct mCore*c){unsigned low=probeHigh,irq=irqHigh;for(unsigned a=probeLow;a<probeHigh;a+=4)if(c->busRead32(c,a)!=0xDDAADDCC){low=a;break;}for(unsigned a=irqLow;a<irqHigh;a+=4)if(c->busRead32(c,a)!=0xDDAADDCC){irq=a;break;}fprintf(stderr,"STACK_OBSERVATION user_free=%u user_touched_from_top=%u irq_touched=%u allocated_user=%u allocated_irq=%u\\n",low-probeLow,irqLow-low,irqHigh-irq,irqLow-probeLow,irqHigh-irqLow);assert(low>probeLow&&irq>irqLow);}
